import threading

# Fast at low contention, cliffs at high contention:
# one lock / one cache line is the serial section.
class SingleCounter:
    def __init__(self):
        self._lock = threading.Lock()
        self._n = 0
    def incr(self):
        with self._lock:
            self._n += 1
    def get(self):
        with self._lock:
            return self._n

# Slower per op (hash + scatter), scales with threads:
# throughput grows with stripes, read pays the sum.
class ShardedCounter:
    def __init__(self, stripes=16):
        self._stripes = stripes
        self._locks = [threading.Lock() for _ in range(stripes)]
        self._counts = [0] * stripes
    def incr(self, key_hash: int):
        i = hash(key_hash) % self._stripes
        with self._locks[i]:
            self._counts[i] += 1
    def get(self):
        total = 0
        for i in range(self._stripes):
            with self._locks[i]:
                total += self._counts[i]
        return total
